:root {
  --ink: #1d2940;
  --navy: #283b68;
  --paper: #fffdf5;
  --line: #d9d3c2;
  --gold: #efb94f;
  --mist: #edf1fa;
}

.pass {
  width: 456px;
  box-sizing: border-box;
  padding: 16px;
  border: 1px solid var(--line);
  border-radius: 16px;
  background: var(--paper);
  color: var(--ink);
}

.pass-header {
  display: flex;
  align-items: center;
  gap: 12px;
}

.orbit {
  display: grid;
  width: 42px;
  height: 42px;
  place-items: center;
  border-radius: 50%;
  background: var(--navy);
  color: var(--gold);
  font-size: 22px;
}

.eyebrow {
  margin: 0 0 2px;
  color: var(--navy);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  line-height: 1.2;
  text-transform: uppercase;
}

h1 {
  margin: 0;
  font-size: 21px;
  line-height: 1.15;
}

.details {
  display: flex;
  gap: 28px;
  margin: 16px 0;
  padding: 10px 0;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}

.details p {
  display: grid;
  gap: 3px;
  margin: 0;
  font-size: 13px;
  line-height: 1.25;
}

.details strong {
  color: var(--navy);
  font-size: 10px;
  letter-spacing: 0.07em;
}

.pass-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  color: var(--navy);
  font-size: 13px;
  font-weight: 600;
}

button {
  padding: 7px 11px;
  border: 0;
  border-radius: 8px;
  background: var(--mist);
  color: var(--navy);
  font-size: 12px;
  font-weight: 700;
}
